class Orders
  include Enumerable

  def initialize(items = [])
    @items = items.freeze                # no in-place edits from the class either
  end

  def each(&block) = @items.each(&block) # Enumerable builds on #each

  def add(order)
    raise OrderLimit if @items.size >= MAX_ORDERS
    Orders.new(@items + [order])          # new collection, never mutates @items
  end

  def total = @items.sum(&:amount)
end
